vyatta_cfg_run () 
{ 
    if [[ "$1" == "set" && "$2" =~ ^(-|\+).* ]]; then
        set "${@:2}";
        return;
    fi;
    local cmd=$1;
    local -a args=("$@");
    local -a filtered_cmds;
    get_prefix_filtered_list $cmd _vyatta_cfg_cmds filtered_cmds;
    local found;
    is_elem_of "${cmd}" _vyatta_cfg_cmds;
    found=$?;
    stty echo 2> /dev/null;
    if [[ "${#filtered_cmds[@]}" == "0" ]]; then
        echo -ne "\n  Invalid command: [$cmd]\n\n" 1>&2;
        return 1;
    else
        if [[ "${#filtered_cmds[@]}" != "1" && "$found" == "1" ]]; then
            echo -ne "\n  Ambiguous command: [$cmd]\n" 1>&2;
            local -a fitems=();
            local -a fstrs=();
            local -a _get_help_text_items=("${_vyatta_cfg_cmds[@]}");
            local -a _get_help_text_helps=("${_vyatta_cfg_helps[@]}");
            get_prefix_filtered_list2 "$cmd" _get_help_text_items fitems _get_help_text_helps fstrs;
            _get_help_text_items=("${fitems[@]}");
            _get_help_text_helps=("${fstrs[@]}");
            get_help_text;
            echo -e "$vyatta_help_text\n" | sed 's/^P/  P/';
            return 1;
        fi;
    fi;
    local fcmd;
    if is_elem_of "${cmd}" _vyatta_cfg_cmds; then
        fcmd=$cmd;
    else
        fcmd=${filtered_cmds[0]};
    fi;
    case $fcmd in 
        compare)
            vyatta_config_compare "${@:2}"
        ;;
        comment)
            vyatta_config_comment "${args[@]}"
        ;;
        copy | rename)
            vyatta_config_copy $fcmd ${@:2}
        ;;
        exit)
            vyatta_config_exit "${@:2}"
        ;;
        run)
            vyatta_config_run "${@:2}"
        ;;
        load)
            vyatta_config_load "${@:2}"
        ;;
        commit)
            vyatta_config_commit "${@:2}"
        ;;
        confirm)
            vyatta_config_confirm "${@:2}"
        ;;
        rollback)
            vyatta_config_rollback "${@:2}"
        ;;
        rollback-soft)
            vyatta_config_rollback-soft "${@:2}"
        ;;
        commit-confirm)
            vyatta_config_commit-confirm "${@:2}"
        ;;
        compare)
            vyatta_config_compare "${@:2}"
        ;;
        save)
            vyatta_config_save "${@:2}"
        ;;
        merge)
            vyatta_config_merge "${@:2}"
        ;;
        *)
            vyatta_cfg_cmd $fcmd "${@:2}"
        ;;
    esac
}

vyatta_cfg_cmd () 
{ 
    local cmd=$1;
    if [[ "$#" == "1" ]]; then
        vyatta_cfg_cmd_run $cmd;
        return;
    fi;
    local -a args=("$@");
    local -a expanded_api_args=();
    if test -f "/var/run/vyconf_backend"; then
        local editlvl=$(${vyconf_bin_dir}/vyconf_cli_compat getEditLevelStr);
    else
        local editlvl=$(cli-shell-api getEditLevelStr);
    fi;
    vyatta_config_expand_compwords "${args[@]}";
    if test -f "/var/run/vyconf_backend"; then
        if [[ "${expanded_api_args[@]:$[${#expanded_api_args[@]}-1]}" == "-all" ]] && [[ "${expanded_api_args[0]}" == "show" ]]; then
            if [[ $[${#expanded_api_args[@]}-2] -eq 0 ]]; then
                vyatta_cfg_cmd_run "${expanded_api_args[@]}";
            else
                if ${vyconf_bin_dir}/vyconf_cli_compat validateTmplPath ${editlvl[*]} "${expanded_api_args[@]:1:$[${#expanded_api_args[@]}-2]}"; then
                    vyatta_cfg_cmd_run "${expanded_api_args[@]}";
                else
                    vyatta_cfg_validate_cmd "${expanded_api_args[@]}";
                fi;
            fi;
        else
            if ${vyconf_bin_dir}/vyconf_cli_compat validateTmplPath ${editlvl[*]} "${expanded_api_args[@]:1}"; then
                vyatta_cfg_cmd_run "${expanded_api_args[@]}";
            else
                vyatta_cfg_validate_cmd "${expanded_api_args[@]}";
            fi;
        fi;
    else
        if [[ "${expanded_api_args[@]:$[${#expanded_api_args[@]}-1]}" == "-all" ]] && [[ "${expanded_api_args[0]}" == "show" ]]; then
            if [[ $[${#expanded_api_args[@]}-2] -eq 0 ]]; then
                vyatta_cfg_cmd_run "${expanded_api_args[@]}";
            else
                if cli-shell-api validateTmplPath -- ${editlvl[*]} "${expanded_api_args[@]:1:$[${#expanded_api_args[@]}-2]}"; then
                    vyatta_cfg_cmd_run "${expanded_api_args[@]}";
                else
                    vyatta_cfg_validate_cmd "${expanded_api_args[@]}";
                fi;
            fi;
        else
            if cli-shell-api validateTmplPath -- ${editlvl[*]} "${expanded_api_args[@]:1}"; then
                vyatta_cfg_cmd_run "${expanded_api_args[@]}";
            else
                vyatta_cfg_validate_cmd "${expanded_api_args[@]}";
            fi;
        fi;
    fi
}

vyatta_cfg_cmd_run () 
{ 
    local cmd=$1;
    local output='';
    if [[ "$cmd" == "edit" ]]; then
        vyatta_config_edit "${@:2}";
    else
        if [[ "$cmd" == "show" ]]; then
            vyatta_config_show "${@:2}";
        else
            if test -f "/var/run/vyconf_backend"; then
                cmd="${vyconf_bin_dir}/vy_$cmd";
            else
                cmd="/opt/vyatta/sbin/my_$cmd";
            fi;
            output=$($cmd "${@:2}");
        fi;
    fi;
    vyatta_cfg_print_output "$output"
}
vyatta_cfg_validate_cmd () 
{ 
    local cmd=$1;
    local -a expanded_api_args=("$@");
    if test -f "/var/run/vyconf_backend"; then
        local editlvl=$(${vyconf_bin_dir}/vyconf_cli_compat getEditLevelStr);
    else
        local editlvl=$(cli-shell-api getEditLevelStr);
    fi;
    local path='';
    local opath='';
    for arg in "${expanded_api_args[@]:1}";
    do
        if [[ "$path" == '' ]]; then
            path="$arg";
        else
            path="$path $arg";
        fi;
        if test -f "/var/run/vyconf_backend"; then
            if ! ${vyconf_bin_dir}/vyconf_cli_compat validateTmplPath ${editlvl} ${path}; then
                _cli_shell_api_comp_values=();
                vyos_cli_shell_api getCompletionEnv $cmd ${path};
                if [[ "${#_cli_shell_api_comp_values[@]}" != "1" && "${#_cli_shell_api_comp_values[@]}" != "0" ]]; then
                    local -a _get_help_text_items=("${_cli_shell_api_hitems[@]}");
                    local -a _get_help_text_helps=("${_cli_shell_api_hstrs[@]}");
                    local vyatta_help_text='';
                    if [[ $opath == '' ]]; then
                        echo -ne "\n  Configuration path: [$arg] is ambiguous\n" 1>&2;
                    else
                        echo -ne "\n  Configuration path: $opath [$arg] is ambiguous\n" 1>&2;
                    fi;
                    get_help_text;
                    echo -e "$vyatta_help_text\n" | sed 's/^P/  P/';
                    echo -e "  ${cmd^} failed\n";
                    break;
                else
                    if [[ $opath == '' ]]; then
                        echo -ne "\n  Configuration path: [$arg] is not valid\n  ${cmd^} failed\n\n" 1>&2;
                    else
                        echo -ne "\n  Configuration path: $opath [$arg] is not valid\n  ${cmd^} failed\n\n" 1>&2;
                    fi;
                    break;
                fi;
            else
                opath=$path;
            fi;
        else
            if ! cli-shell-api validateTmplPath -- ${editlvl} ${path}; then
                _cli_shell_api_comp_values=();
                vyatta_cli_shell_api getCompletionEnv $cmd ${path};
                if [[ "${#_cli_shell_api_comp_values[@]}" != "1" && "${#_cli_shell_api_comp_values[@]}" != "0" ]]; then
                    local -a _get_help_text_items=("${_cli_shell_api_hitems[@]}");
                    local -a _get_help_text_helps=("${_cli_shell_api_hstrs[@]}");
                    local vyatta_help_text='';
                    if [[ $opath == '' ]]; then
                        echo -ne "\n  Configuration path: [$arg] is ambiguous\n" 1>&2;
                    else
                        echo -ne "\n  Configuration path: $opath [$arg] is ambiguous\n" 1>&2;
                    fi;
                    get_help_text;
                    echo -e "$vyatta_help_text\n" | sed 's/^P/  P/';
                    echo -e "  ${cmd^} failed\n";
                    break;
                else
                    if [[ $opath == '' ]]; then
                        echo -ne "\n  Configuration path: [$arg] is not valid\n  ${cmd^} failed\n\n" 1>&2;
                    else
                        echo -ne "\n  Configuration path: $opath [$arg] is not valid\n  ${cmd^} failed\n\n" 1>&2;
                    fi;
                    break;
                fi;
            else
                opath=$path;
            fi;
        fi;
    done
